let undoManager = UndoManager()

func insert(_ text: String, at pos: Int, into doc: Document) {
    doc.insert(text, at: pos)
    undoManager.registerUndo(withTarget: doc) { $0.remove(at: pos, count: text.count) }
}

undoManager.undo()      // redo is recorded automatically

